<script lang="ts">
    import DeviceIcon from "./DeviceIcon.svelte";
    import type { UiSnapshot,UiCommands } from "./types";
    let {view,commands}:{view:UiSnapshot;commands:UiCommands}=$props();
    let th=$derived(view.language==="th");
    let data=$derived(view.community);
    let trade=$derived(data?.trade??null);
    let locked=$derived(!view.online||view.communityPending||trade?.pending===true);
    let handle=$state("");let gold:number|undefined=$state(0);let quantities=$state<Record<string,number>>({});
    let selectedPack=$state("");let lastOffer="";
    $effect(()=>{const signature=JSON.stringify([trade?.id,trade?.mine]);if(signature!==lastOffer){lastOffer=signature;gold=trade?.mine.gold??0;quantities={...trade?.mine.items};}});
    let draft=$derived({gold:gold??-1,items:Object.fromEntries(Object.entries(quantities).filter(([,n])=>n>0).sort(([a],[b])=>a.localeCompare(b)))});
    let dirty=$derived(trade!==null&&(draft.gold!==trade.mine.gold||JSON.stringify(draft.items)!==JSON.stringify(Object.fromEntries(Object.entries(trade.mine.items).sort(([a],[b])=>a.localeCompare(b))))));
    let invalid=$derived(!Number.isSafeInteger(gold)||Number(gold)<0||Number(gold)>Math.min(1_000_000,data?.gold??0)||Object.keys(draft.items).length>6);
    let packs=$derived((data?.packs??[]).map(([id,credits])=>({id,credits})));
    const name=(id:string)=>view.inventory.items.find(i=>i.id===id)?.label??id.replaceAll("_"," ");
    function invite(event:SubmitEvent){event.preventDefault();if(!locked&&/^[a-fA-F0-9]{8}$/.test(handle))commands.community({kind:"invite",handle:handle.toLowerCase()});}
</script>

<div class="community-panel" aria-busy={view.communityPending}>
    <nav class="community-nav" aria-label={th?"ระบบผู้เล่น":"Player systems"}>{#each [{id:"trade",en:"Trade",th:"แลกเปลี่ยน"},{id:"battlepass",en:"Battle Pass",th:"แบตเทิลพาส"},{id:"topup",en:"Test Top-up",th:"เติมเงินทดสอบ"}] as tab}<button type="button" class:active={view.modal===tab.id} aria-current={view.modal===tab.id?"page":undefined} onclick={()=>commands.panels.openPanel(tab.id as "trade"|"battlepass"|"topup")}>{th?tab.th:tab.en}</button>{/each}</nav>
    {#if !view.online&&!data}<p class="status-note" role="status">{th?"เข้าห้องออนไลน์เพื่อใช้งานระบบนี้":"Join an online room to use these systems."}</p>
    {:else if !data}<p class="status-note" role="status">{th?"กำลังขอข้อมูลจากเซิร์ฟเวอร์…":"Waiting for server data…"}</p><button type="button" onclick={()=>commands.community({kind:"sync",device:"unknown"})}>{th?"โหลดข้อมูลใหม่":"Refresh"}</button>
    {:else if view.modal === "trade"}
        <p class="status-note">{th?"เทรดกับผู้เล่นในห้องเดียวกัน ระยะไม่เกิน 12 เมตร · แลกทองและของที่ไม่ได้สวมใส่":"Same room · within 12 m · gold and unequipped items"}</p>
        {#if !trade}
            <form class="invite-form" onsubmit={invite}><label for="trade-handle">{th?"รหัสผู้เล่น":"Player handle"}</label><div><input id="trade-handle" bind:value={handle} maxlength="8" placeholder="a1b2c3d4" autocomplete="off" spellcheck="false"/><button type="submit" disabled={locked||!/^[a-fA-F0-9]{8}$/.test(handle)}>{th?"ขอเทรด":"Invite to trade"}</button></div></form>
            <h3>{th?"ผู้เล่นใกล้คุณ":"Nearby players"}</h3>
            <div class="player-list">{#each data.players as player (player.handle)}<div class="player-row"><div><strong><DeviceIcon device={player.device} thai={th}/>{player.name}</strong><small>@{player.handle}</small></div><button type="button" disabled={locked||!player.nearby} onclick={()=>commands.community({kind:"invite",handle:player.handle})}>{player.nearby?(th?"เทรด":"Trade"):(th?"ไกลเกินไป":"Too far")}</button></div>{:else}<p class="status-note">{th?"ยังไม่มีผู้เล่นอื่นในห้องนี้":"No other players in this room yet."}</p>{/each}</div>
        {:else}
            <div class="trade-heading"><div><p class="eyebrow">{th?"คู่แลกเปลี่ยน":"TRADING WITH"}</p><h3><DeviceIcon device={trade.peer_device} thai={th}/>{trade.peer}</h3></div><span class="revision">{th?"ข้อเสนอ":"Offer"} #{trade.revision}</span></div>
            {#if !trade.accepted}<p class="status-note">{trade.incoming?(th?"ตรวจชื่อคู่เทรดแล้วกดยอมรับคำเชิญ":"Review the player name, then accept the invitation."):(th?"กำลังรอคู่เทรดยอมรับคำเชิญ…":"Waiting for your partner to accept…")}</p>{#if trade.incoming}<button type="button" class="primary" disabled={locked} onclick={()=>commands.community({kind:"accept",trade:trade.id,revision:trade.revision})}>{th?"ยอมรับคำเชิญ":"Accept invitation"}</button>{/if}
            {:else}
                <div class="offer-columns"><section><h3>{th?"ข้อเสนอของคุณ":"Your offer"}</h3><label for="trade-gold">{th?"ทอง":"Gold"} <small>({data.gold.toLocaleString()})</small></label><input id="trade-gold" type="number" min="0" max={Math.min(1_000_000,data.gold)} step="1" bind:value={gold} disabled={locked}/><div class="offer-items">{#each data.items as item (item.id)}<label class="quantity-row"><span>{name(item.id)}<small>× {item.count}</small></span><input type="number" min="0" max={item.count} step="1" aria-label={`${th?"จำนวน":"Quantity"} ${name(item.id)}`} value={quantities[item.id]??0} disabled={locked} oninput={(e)=>quantities={...quantities,[item.id]:Math.max(0,Math.min(item.count,Math.floor(Number(e.currentTarget.value)||0)))}}/></label>{/each}</div><button type="button" disabled={locked||invalid||!dirty} onclick={()=>commands.community({kind:"offer",trade:trade.id,revision:trade.revision,offer:draft})}>{th?"ส่งข้อเสนอใหม่":"Update offer"}</button></section>
                <section class="partner-offer"><h3>{th?"คุณจะได้รับ":"You receive"}</h3><strong class="gold-total">{trade.theirs.gold.toLocaleString()} {th?"ทอง":"Gold"}</strong><ul>{#each Object.entries(trade.theirs.items) as [id,count]}<li>{name(id)} <strong>× {count}</strong></li>{:else}<li class="status-note">{th?"ไม่มีไอเท็ม":"No items offered"}</li>{/each}</ul><p class="confirm-data">{trade.peer_confirmed?(th?"คู่เทรดยืนยันแล้ว":"Partner confirmed"):(th?"รอคู่เทรดยืนยัน":"Awaiting partner confirmation")}</p></section></div>
                <p class="status-note">{dirty?(th?"ส่งข้อเสนอที่แก้ไขก่อนยืนยัน":"Submit your edited offer before confirming."):(th?"ตรวจทั้งสองฝั่งก่อนยืนยัน การแก้ข้อเสนอจะล้างคำยืนยันทั้งคู่":"Review both sides. Any offer change clears both confirmations.")}</p>
                <button type="button" class="primary" disabled={locked||dirty||trade.confirmed} onclick={()=>commands.community({kind:"confirm",trade:trade.id,revision:trade.revision})}>{trade.pending?(th?"กำลังบันทึก…":"Finalising…"):trade.confirmed?(th?"ยืนยันแล้ว รออีกฝ่าย":"Confirmed · waiting"):th?"ยืนยันข้อเสนอทั้งสองฝั่ง":"Confirm both offers"}</button>
            {/if}
            <button type="button" class="cancel" disabled={locked} onclick={()=>commands.community({kind:"cancel",trade:trade.id})}>{th?"ยกเลิกการเทรด":"Cancel trade"}</button>
        {/if}
    {:else if view.modal === "battlepass"}
        <div class="season-hero"><p class="eyebrow">SUNMEADOW · PREVIEW SEASON</p><h3>{th?"เส้นทางผู้พิทักษ์ทุ่งแสง":"Wardens of Sunmeadow"}</h3><p>{th?"ปราบมอนสเตอร์ สะสม 10 EXP ต่อครั้ง ปลดล็อกรางวัลสองเส้นทาง":"Defeat monsters · 10 season XP per credited kill · two reward tracks"}</p><div class="season-progress"><progress value={data.xp} max={data.tiers*data.xp_per_tier} aria-label={th?"ความคืบหน้าซีซัน":"Season progress"}></progress><strong>{Math.floor(data.xp/data.xp_per_tier)} / {data.tiers}</strong></div><small>{data.xp.toLocaleString()} / 2,000 EXP</small></div>
        <div class="premium-callout"><div><strong>{data.premium?(th?"Premium เปิดแล้ว":"Premium unlocked"):th?"เปิดเส้นทาง Premium":"Unlock the Premium track"}</strong><small>{th?"ซีซันทดลอง ใช้เครดิตทดลองเท่านั้น ไม่รับเงินจริง":"Preview season · preview credits only · no real payment"}</small></div><button type="button" disabled={locked||data.premium||!data.test_enabled||data.test_credits<data.premium_test_cost} onclick={()=>commands.community({kind:"pass_premium",season:data.season,op_id:crypto.randomUUID()})}>{data.premium?(th?"เปิดใช้งานแล้ว":"Active"):`${data.premium_test_cost} ${th?"เครดิตทดลอง":"preview credits"}`}</button></div>
        <div class="reward-table"><div class="reward-header"><span>{th?"ขั้น":"Tier"}</span><strong>FREE</strong><strong>PREMIUM</strong></div>{#each Array.from({length:data.tiers},(_,i)=>i+1) as tier}<div class="reward-row" class:unlocked={data.xp>=tier*data.xp_per_tier}><span class="tier-badge">{tier}</span>{#each [false,true] as premium}{@const claimed=((premium?data.premium_claims:data.free_claims)&(1<<(tier-1)))!==0}<div class="reward-cell" class:premium><span>{data.rewards[tier-1][premium?2:1]} {th?"ทอง":"Gold"}</span><button type="button" disabled={locked||claimed||data.xp<tier*data.xp_per_tier||(premium&&!data.premium)} onclick={()=>commands.community({kind:"pass_claim",season:data.season,tier,premium,op_id:crypto.randomUUID()})}>{claimed?(th?"รับแล้ว":"Claimed"):data.xp<tier*data.xp_per_tier?`${tier*100} EXP`:premium&&!data.premium?(th?"ล็อก Premium":"Premium locked"):th?"รับรางวัล":"Claim"}</button></div>{/each}</div>{/each}</div>
    {:else}
        <div class="test-banner"><strong>{th?"โหมดทดสอบ ไม่รับเงินจริง":"TEST MODE · NO REAL PAYMENT"}</strong><p>{th?"เครดิตทดลองแยกจาก Coin ในเกม แลกเปลี่ยนหรือถอนเงินไม่ได้ ใช้ทดลองเปิด Premium เท่านั้น":"Preview credits are separate from in-game Coin. They cannot be traded or withdrawn; use them to test Premium."}</p></div>
        <div class="credit-balance"><span>{th?"เครดิตทดลอง":"Preview balance"}</span><strong>{data.test_credits.toLocaleString()}</strong></div>
        {#if !data.test_enabled}<p class="status-note" role="status">{th?"ยังไม่เปิดบริการทดสอบบนเซิร์ฟเวอร์นี้":"This server has not enabled test commerce."}</p>{/if}
        <div class="pack-grid">{#each packs as pack}<button type="button" class="credit-pack" disabled={locked||!data.test_enabled||data.order_count>=64} onclick={()=>selectedPack=pack.id}><span aria-hidden="true">✧</span><strong>{pack.credits}</strong><small>{th?"เครดิตทดลอง ฟรี":"Preview credits · free"}</small></button>{/each}</div>
        {#if selectedPack}<div class="order-confirm" role="region" aria-label={th?"ยืนยันรายการทดสอบ":"Confirm test order"}><p>{th?"เพิ่มเครดิตทดลอง ไม่มีการตัดเงิน":"Add preview credits. No money will be charged."}</p><button type="button" class="primary" disabled={locked} onclick={()=>{commands.community({kind:"test_topup",pack:selectedPack,op_id:crypto.randomUUID()});selectedPack="";}}>{th?"ยืนยันรายการทดสอบ":"Confirm test order"}</button><button type="button" onclick={()=>selectedPack=""}>{th?"ยกเลิก":"Cancel"}</button></div>{/if}
        <h3>{th?"รายการทดสอบล่าสุด":"Recent preview orders"}</h3><ol class="order-list">{#each data.orders as order (order.id)}<li><strong>+{order.credits} <small>{th?"เครดิตทดลอง":"preview credits"}</small></strong><code title={order.id}>{order.id.slice(0,8)}</code><span>{th?"สำเร็จ":"Completed"}</span></li>{:else}<li class="status-note">{th?"ยังไม่มีรายการ":"No preview orders yet."}</li>{/each}</ol>
    {/if}
    {#if view.communityPending}<p class="status-note" role="status">{th?"กำลังรอเซิร์ฟเวอร์…":"Waiting for the server…"}</p>{/if}
</div>

<style>
.community-panel{display:grid;gap:16px;color:#e4edf2;line-height:1.6}.community-panel :is(p,h3,ul,ol){margin:0}.community-panel h3{color:#edd4a0;font-family:"Marcellus",serif;font-size:21px}.community-panel button,.community-panel input{font:inherit;min-height:44px;border:1px solid #596670;border-radius:6px;padding:8px 12px;color:#d9ebf2;background:#142731}.community-panel button{cursor:pointer;transition:background 150ms,border-color 150ms}.community-panel button:hover:enabled{background:#254653;border-color:#86d9ef}.community-panel button:disabled{opacity:.48;cursor:default}.community-panel :is(button,input):focus-visible{outline:3px solid #8ee5ff;outline-offset:3px}.community-nav{display:flex;gap:6px}.community-nav button{flex:1;padding:8px 5px;font-size:13px}.community-nav .active{border-color:#86d9ef;background:#203e4d}.status-note{color:#bbc8d2;font-size:13px}.eyebrow{font-size:11px;letter-spacing:.16em;color:#aacfe2}.invite-form{display:grid;gap:6px}.invite-form>div{display:flex;gap:8px}.invite-form input{min-width:0;flex:1}.player-list{display:grid;gap:8px}.player-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;background:#172832;border:1px solid #344955;border-radius:6px}.player-row small,.premium-callout small,.quantity-row small{display:block;color:#a9bcc8;font-size:12px}.trade-heading{display:flex;align-items:center;justify-content:space-between}.revision{font-size:12px;color:#a9bcc8}.offer-columns{display:grid;grid-template-columns:1fr 1fr;gap:12px}.offer-columns section{display:grid;align-content:start;gap:10px;padding:14px;background:#12212b;border:1px solid #3b5668;border-radius:8px}.offer-columns input{width:100%;box-sizing:border-box}.offer-items{display:grid;gap:8px;max-height:240px;overflow:auto}.quantity-row{display:grid;grid-template-columns:1fr 64px;gap:8px;align-items:center;font-size:13px}.quantity-row input{text-align:center;padding:6px}.partner-offer ul{padding-left:18px;font-size:13px}.gold-total{color:#eed493;font-variant-numeric:tabular-nums}.confirm-data{color:#86d9ef;font-size:13px}.community-panel .primary{background:#194354;border-color:#73bed6;font-weight:650}.community-panel .cancel{justify-self:start;background:transparent;color:#c4ced6}.season-hero{padding:22px;border:1px solid #516371;border-radius:8px;background:radial-gradient(ellipse at 95% 0,#294e65,transparent 65%),#152534}.season-hero p:not(.eyebrow){font-size:13px;color:#bacedd;margin-top:8px}.season-hero h3{font-size:28px}.season-progress{display:flex;align-items:center;gap:12px;margin-top:18px}.season-progress progress{height:10px;width:100%;accent-color:#76d7ed}.season-progress strong{white-space:nowrap}.season-hero small{color:#bacedd}.premium-callout{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px;border:1px solid #776443;border-radius:8px;background:#292619}.premium-callout strong{color:#f0d39b}.premium-callout button{max-width:45%;font-size:12px}.reward-table{display:grid;gap:7px}.reward-header,.reward-row{display:grid;grid-template-columns:44px 1fr 1fr;gap:8px;align-items:center}.reward-header{font-size:12px;color:#91b8ca;letter-spacing:.1em}.reward-header strong:last-child{color:#eed397}.reward-row{padding:8px 0;border-bottom:1px solid #304352}.tier-badge{width:30px;height:30px;border:1px solid #53646e;display:grid;place-items:center;border-radius:50%;color:#a3b5c1;font-variant-numeric:tabular-nums}.unlocked .tier-badge{color:#a4e9ff;border-color:#79c9e1}.reward-cell{display:grid;gap:5px;padding:9px;border:1px solid #365362;background:#152b37;border-radius:7px;font-size:13px}.reward-cell.premium{border-color:#756440;background:#2a261b;color:#ecd4a4}.reward-cell button{min-height:36px;font-size:12px;padding:5px}.test-banner{padding:16px;border:1px solid #7e7751;border-radius:7px;background:#29281d}.test-banner strong{color:#ffe2a2;font-size:13px}.test-banner p{font-size:13px;margin-top:6px;color:#c9cbbc}.credit-balance{display:flex;align-items:baseline;justify-content:space-between;padding:12px 0}.credit-balance strong{font-size:30px;color:#97e7ff;font-variant-numeric:tabular-nums}.pack-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.community-panel .credit-pack{display:grid;gap:4px;background:radial-gradient(ellipse at 50% 0,#30435a,transparent 75%),#172733;padding:16px 8px}.credit-pack>span{font-size:25px;color:#8de3ff}.credit-pack>strong{font-size:25px}.credit-pack small{font-size:11px;color:#b6c7d2}.order-confirm{display:flex;gap:8px;flex-wrap:wrap;padding:14px;border:1px solid #668fa3;border-radius:7px}.order-confirm p{flex:0 0 100%;font-size:13px}.order-list{padding:0;list-style:none;display:grid;gap:8px}.order-list li{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #34454d;font-size:13px}.order-list strong{flex:1}.order-list small{font-size:11px;font-weight:400;color:#afc0cb}.order-list code{font-size:11px;color:#91a5b3}.order-list li>span{color:#89d9e7;font-size:12px}
@media(max-width:480px){.offer-columns{grid-template-columns:1fr}.premium-callout{flex-wrap:wrap}.premium-callout button{max-width:100%}.pack-grid{gap:6px}.reward-header,.reward-row{grid-template-columns:30px 1fr 1fr;gap:5px}.community-nav button{font-size:12px}}@media(prefers-reduced-motion:reduce){.community-panel button{transition:none}}
</style>
